{"file_text": "@page "/chat"
@using sv_6a2f3a9cd7674a4c947c93bc62a99c43.Services
@rendermode InteractiveServer
@inject IChatService ChatService
@implements IAsyncDisposable
@inject IJSRuntime JS

<PageTitle>Team Chat</PageTitle>

<div class="chat-layout">
    <aside class="chat-sidebar">
        <ChannelList Channels="channels"
                     ActiveChannelId="activeChannelId"
                     OnChannelSelected="SelectChannel" />
    </aside>

    <main class="chat-main @(threadRootMessage is null ? "full-width" : "")">
        @if (activeChannel is not null)
        {
            <MessageArea Channel="activeChannel"
                         Messages="messages"
                         ThreadReplyCounts="threadReplyCounts"
                         IsLoadingMore="isLoadingMore"
                         OnSendMessage="SendMessage"
                         OnOpenThread="OpenThread"
                         OnReact="AddReaction"
                         OnLoadMore="LoadMoreMessages" />
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </main>

    @if (threadRootMessage is not null)
    {
        <aside class="chat-thread">
            <ThreadPanel RootMessage="threadRootMessage"
                         Replies="threadReplies"
                         IsLoading="isLoadingThread"
                         OnClose="CloseThread"
                         OnReply="SendThreadReply" />
        </aside>
    }
</div>

@code {
    private List<Channel> channels = [];
    private List<Message> messages = [];
    private Dictionary<int, int> threadReplyCounts = [];
    private Channel? activeChannel;
    private int activeChannelId;
    private bool isLoadingMore;

    // Thread state
    private Message? threadRootMessage;
    private List<Message> threadReplies = [];
    private bool isLoadingThread;

    // Pagination
    private const int PageSize = 30;
    private int currentSkip;
    private bool hasMoreMessages = true;

    // Scroll detection
    private IJSObjectReference? scrollModule;
    private DotNetObjectReference<Chat>? dotNetRef;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            dotNetRef = DotNetObjectReference.Create(this);
            scrollModule = await JS.InvokeAsync<IJSObjectReference>("import", "./Components/Pages/Chat.razor.js");
            await scrollModule.InvokeVoidAsync("initScrollDetection", ".message-list", dotNetRef);
        }
    }

    [JSInvokable]
    public async Task OnScrolledToTop()
    {
        if (!isLoadingMore && hasMoreMessages)
        {
            await LoadMoreMessages();
            StateHasChanged();
        }
    }

    private async Task SelectChannel(int channelId)
    {
        activeChannelId = channelId;
        activeChannel = channels.FirstOrDefault(c => c.Id == channelId);
        currentSkip = 0;
        hasMoreMessages = true;
        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        currentSkip = messages.Count;

        await ChatService.MarkChannelReadAsync(channelId);
        await ComputeThreadReplyCounts();
    }

    private async Task LoadMoreMessages()
    {
        if (isLoadingMore || !hasMoreMessages) return;

        isLoadingMore = true;
        var older = await ChatService.GetMessagesAsync(activeChannelId, currentSkip, PageSize);
        if (older.Count < PageSize) hasMoreMessages = false;
        messages.InsertRange(0, older);
        currentSkip += older.Count;
        isLoadingMore = false;

        await ComputeThreadReplyCounts();
    }

    private async Task SendMessage(string content)
    {
        var message = await ChatService.SendMessageAsync(activeChannelId, content, null);
        messages.Add(message);
    }

    private async Task OpenThread(int messageId)
    {
        isLoadingThread = true;
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        threadReplies = [];
        StateHasChanged();

        threadReplies = await ChatService.GetThreadAsync(messageId);
        isLoadingThread = false;
    }

    private void CloseThread()
    {
        threadRootMessage = null;
        threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(activeChannelId, content, threadRootMessage.Id);
        threadReplies.Add(reply);

        // Update reply count
        threadReplyCounts[threadRootMessage.Id] = threadReplies.Count;
    }

    private async Task AddReaction((int MessageId, string Emoji) reaction)
    {
        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);

        // Optimistically update the UI
        var message = messages.FirstOrDefault(m => m.Id == reaction.MessageId);
        if (message is not null)
        {
            var existing = message.Reactions.FirstOrDefault(r => r.Emoji == reaction.Emoji);
            if (existing is not null)
            {
                existing.Users.Add("You");
            }
            else
            {
                message.Reactions.Add(new Reaction(reaction.Emoji, ["You"]));
            }
        }
    }

    private Task ComputeThreadReplyCounts()
    {
        // Count messages that are replies to other messages in the current set
        threadReplyCounts = messages
            .Where(m => m.ReplyToId.HasValue)
            .GroupBy(m => m.ReplyToId!.Value)
            .ToDictionary(g => g.Key, g => g.Count());
        return Task.CompletedTask;
    }

    public async ValueTask DisposeAsync()
    {
        if (scrollModule is not null)
        {
            await scrollModule.DisposeAsync();
        }
        dotNetRef?.Dispose();
    }
}
